files.content:
:root {
  --bg: #1a1c2c;
  --card: #2a2d45;
  --accent: #ffcd75;
  --text: #f4f4f4;
  --muted: #8b8fa3;
  --btn: #5d275d;
  --btn-hover: #7a3a7a;
  --btn-active: #3e1a3e;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background: var(--bg);
  background-image: radial-gradient(circle, #2a2d45 1px, transparent 1px);
  background-size: 16px 16px;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
}

.card {
  width: 100%;
  max-width: 420px;
  background: var(--card);
  border: 4px solid var(--accent);
  border-radius: 8px;
  padding: 32px 24px;
  text-align: center;
  box-shadow: 8px 8px 0 #000;
}

.title {
  font-size: 1.25rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 24px;
}

.mode {
  display: inline-block;
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: 3px;
  padding: 6px 16px;
  border: 3px solid var(--accent);
  border-radius: 4px;
  color: var(--accent);
  margin-bottom: 16px;
}

.timer {
  font-family: 'Courier New', monospace;
  font-size: clamp(3rem, 18vw, 5rem);
  font-weight: 700;
  letter-spacing: 4px;
  line-height: 1.1;
  margin: 16px 0 32px;
  color: var(--text);
  text-shadow: 4px 4px 0 #000;
}

.controls {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  font-family: inherit;
  font-size: 1.125rem;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--text);
  background: var(--btn);
  border: 3px solid var(--accent);
  border-radius: 4px;
  padding: 14px 28px;
  cursor: pointer;
  box-shadow: 4px 4px 0 #000;
  transition: background 0.1s, transform 0.1s, box-shadow 0.1s;
}

.btn:hover {
  background: var(--btn-hover);
}

.btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

.btn:active {
  background: var(--btn-active);
  transform: translate(4px, 4px);
  box-shadow: 0 0 0 #000;
}

.hint {
  margin-top: 24px;
  font-size: 0.875rem;
  color: var(--muted);
  letter-spacing: 1px;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  .btn {
    padding: 12px 20px;
    font-size: 1rem;
  }
}

(function () {
  'use strict';

  const WORK_SECONDS = 25 * 60;
  const BREAK_SECONDS = 5 * 60;

  const timerEl = document.getElementById('timer');
  const modeEl = document.getElementById('mode');
  const startPauseBtn = document.getElementById('startPause');
  const resetBtn = document.getElementById('reset');

  let mode = 'work';
  let remaining = WORK_SECONDS;
  let running = false;
  let endTime = 0;
  let rafId = null;

  function formatTime(sec) {
    const m = Math.floor(sec / 60);
    const s = sec % 60;
    return String(m).padStart(2, '0') + ':' + String(s).padStart(2, '0');
  }

  function render() {
    timerEl.textContent = formatTime(remaining);
    modeEl.textContent = mode === 'work' ? 'WORK' : 'BREAK';
    startPauseBtn.textContent = running ? 'Pause' : 'Start';
    startPauseBtn.setAttribute('aria-label', running ? 'Pause timer' : 'Start timer');
  }

  function tick() {
    if (!running) return;
    const now = Date.now();
    remaining = Math.max(0, Math.ceil((endTime - now) / 1000));
    if (remaining <= 0) {
      complete();
      return;
    }
    render();
    rafId = requestAnimationFrame(tick);
  }

  function start() {
    if (running) return;
    running = true;
    endTime = Date.now() + remaining * 1000;
    render();
    rafId = requestAnimationFrame(tick);
  }

  function pause() {
    if (!running) return;
    running = false;
    cancelAnimationFrame(rafId);
    remaining = Math.max(0, Math.ceil((endTime - Date.now()) / 1000));
    render();
  }

  function reset() {
    running = false;
    cancelAnimationFrame(rafId);
    mode = 'work';
    remaining = WORK_SECONDS;
    render();
  }

  function complete() {
    running = false;
    cancelAnimationFrame(rafId);
    mode = mode === 'work' ? 'break' : 'work';
    remaining = mode === 'work' ? WORK_SECONDS : BREAK_SECONDS;
    render();
    // Auto-start next session after a brief moment
    setTimeout(start, 800);
  }

  startPauseBtn.addEventListener('click', function () {
    if (running) {
      pause();
    } else {
      start();
    }
  });

  resetBtn.addEventListener('click', reset);

  // Keyboard shortcuts: Space toggles, R resets
  document.addEventListener('keydown', function (e) {
    if (e.target.tagName === 'BUTTON') return;
    if (e.code === 'Space') {
      e.preventDefault();
      startPauseBtn.click();
    } else if (e.key === 'r' || e.key === 'R') {
      reset();
    }
  });

  render();
})();
